import { readFile, writeFile, cp, mkdir, rm } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const root=process.cwd();
const {syncWasmPhpAssets,validatePhpRuntimeAssets}=await import(pathToFileURL(path.join(root,'scripts/sync-wasm-php.mjs')));
const {compressStaticRuntimeAssets}=await import(pathToFileURL(path.join(root,'scripts/compress-static-runtime-assets.mjs')));
const target=path.join(root,'static/wasm-php');
const before=await validatePhpRuntimeAssets(target,{allowCompressed:true});
await cp(target,'/tmp/php-original-assets',{recursive:true});
const next=await syncWasmPhpAssets();
for(const old of before.files.filter(x=>/\.(wasm|so)$/.test(x.path))) {
 const changed=next.manifest.files.find(x=>x.path===old.path);
 assert.deepEqual(changed,old,'Existing PHP engine or extension payload must not change');
}
const scope='/tmp/php-static-scope';
await mkdir(scope,{recursive:true});
await cp(target,path.join(scope,'wasm-php'),{recursive:true});
await compressStaticRuntimeAssets({rootDir:scope});
// Identical decoded binaries retain their exact original compressed delivery bytes.
for(const old of before.files.filter(x=>/\.(wasm|so)$/.test(x.path))) {
 const original=path.join('/tmp/php-original-assets',old.path+'.gz');
 const bytes=await readFile(original).catch(()=>null);
 if(bytes) await writeFile(path.join(scope,'wasm-php',old.path+'.gz'),bytes);
}
await rm(target,{recursive:true});
await cp(path.join(scope,'wasm-php'),target,{recursive:true});
await validatePhpRuntimeAssets(target,{allowCompressed:true});
const manifestPath=path.join(root,'static/compressed-runtime-assets.v1.json');
const manifest=JSON.parse(await readFile(manifestPath,'utf8'));
const phpManifest=JSON.parse(await readFile(path.join(scope,'compressed-runtime-assets.v1.json'),'utf8'));
const isPhp=key=>key.startsWith('wasm-php/');
const nonPhp={assets:manifest.assets.filter(x=>!isPhp(x)),sizes:Object.fromEntries(Object.entries(manifest.sizes).filter(([x])=>!isPhp(x)))};
const merged={...manifest,assets:[...nonPhp.assets,...phpManifest.assets].sort(),sizes:Object.fromEntries([...Object.entries(nonPhp.sizes),...Object.entries(phpManifest.sizes)].sort(([a],[b])=>a.localeCompare(b)))};
assert.deepEqual(merged.assets.filter(x=>!isPhp(x)),nonPhp.assets);
assert.deepEqual(Object.fromEntries(Object.entries(merged.sizes).filter(([x])=>!isPhp(x))),nonPhp.sizes);
// Preserve the existing manifest byte formatting/order when the entry set did not change.
if(JSON.stringify(merged.assets)!==JSON.stringify(manifest.assets)||Object.keys(merged.sizes).some(k=>merged.sizes[k]!==manifest.sizes[k])||Object.keys(merged.sizes).length!==Object.keys(manifest.sizes).length) await writeFile(manifestPath,JSON.stringify(merged,null,2)+'\n');
const hash=createHash('sha256');
for(const directory of ['wasm-assemblyscript','wasm-bash/sdk','wasm-duckdb','wasm-php','wasm-sqlite'].sort()){
 hash.update(directory);
 hash.update(await readFile(path.join(root,'static',directory,'runtime-manifest.v1.json')));
}
const version=hash.digest('hex').slice(0,16);
await writeFile(path.join(root,'src/lib/playground/staticRuntimeModuleVersion.ts'),`// Generated by scripts/build-static-runtime-modules.mjs.\nexport const STATIC_RUNTIME_MODULE_VERSION = '${version}';\n`);
console.log('Verified PHP distribution, unchanged engine/extension payloads and shared cache key',version);
